#!/bin/sh
#
# build.sh : regenerate jal_build.h (JAL_BUILD / JAL_VERSION_STR)
# Copyright (c) 2026, Matthew Schinkel (jalv3compiler fork additions)
# Original: jalv25r9 build script (Kyle A. York / jallib), all rights reserved
#

DST=jal_build.h
rm -f $DST
cat > $DST <<'EOF'
/************************************************************
 **
 ** jal_build.h : build/version configuration
 **
 ** GENERATED by src/jal/build.sh at compile time -- do not edit.
 **
 ** Copyright (c) 2026, Matthew Schinkel
 ** All rights reserved
 **
 ** Based on the jalv25r9 build constants by Kyle A. York.
 ************************************************************/
EOF
echo "#define JAL_BUILD `date +%Y%m%d`" >> $DST
#
# Version string: PINNED since jalv3 3.0a1 (2026-10-09) -- the old
# derive-from-directory-name trick reported whatever folder the tree
# happened to live in.  Style follows Kyle York's originals (jal 2.2 /
# 2.3 / 2.4 banners): "3.0a1" pairs with JAL_VERSION 3000 in jal_main.c
# (major*1000+minor; tracked 2002->2003->2004 in 2007, frozen at 2.4
# upstream, first bumped by this fork).  Override for experimental
# builds: JALV3_VERSION_STR="..." make ...
JAL_VERSION_STR="${JALV3_VERSION_STR:-3.0a1-beta}"
echo "#define JAL_VERSION_STR \"$JAL_VERSION_STR\"" >> $DST

# ROM (A): shared ROM for heap `var string = "..."` via `CALL string_from_array`.
# Default ON: string-heavy programs (the target workload -- many literals and
# many helper calls) save one inline assign path (~390 words / ~768 bytes) per
# site after the first; a single-literal program pays ~300 words for the one
# shared body.  Opt out with EXTRA_CFLAGS=-DJALV2_ROM_A_STRING_LITERAL_CALL=0.
echo "" >> $DST
echo "#ifndef JALV2_ROM_A_STRING_LITERAL_CALL" >> $DST
echo "#define JALV2_ROM_A_STRING_LITERAL_CALL 1" >> $DST
echo "#endif" >> $DST
# ROM (A): only emit CALL string_from_array when const literal byte count >= this (default 2).
# Override: EXTRA_CFLAGS='-DJALV2_ROM_A_STRING_LITERAL_CALL=1 -DJALV2_ROM_A_STRING_LITERAL_CALL_MIN_BYTES=4'
echo "#ifndef JALV2_ROM_A_STRING_LITERAL_CALL_MIN_BYTES" >> $DST
echo "#define JALV2_ROM_A_STRING_LITERAL_CALL_MIN_BYTES 2" >> $DST
echo "#endif" >> $DST
# A heap string actual bound to an `in`-only open byte-array formal passes
# `&heap[payload]` + COUNT(s) instead of snapshotting the text into a
# `_strargN` buffer, when the callee cannot reallocate a heap string (see
# PFILE_PROC_FLAG_STRING_REALLOC).  Opt-out: -DJALV2_STRING_ARG_BYREF=0
echo "" >> $DST
echo "#ifndef JALV2_STRING_ARG_BYREF" >> $DST
echo "#define JALV2_STRING_ARG_BYREF 1" >> $DST
echo "#endif" >> $DST
# A heap string actual bound to an `out`/`in out` open byte-array formal is
# handed over as a payload VIEW (the heap array + a staged base offset; the
# callee reads/writes the live payload through the formal's runtime chunk
# map), when the callee cannot reallocate a heap string; content-only and
# count-bounded (fixes/fix_string_arg_view.md).  Opt-out:
# -DJALV2_STRING_ARG_VIEW=0
echo "" >> $DST
echo "#ifndef JALV2_STRING_ARG_VIEW" >> $DST
echo "#define JALV2_STRING_ARG_VIEW 1" >> $DST
echo "#endif" >> $DST
# Optional: builtin `string_heap_compact()` / `_string_heap_compact()` → machine `CALL string_heap_compact`
# when `include strings_dynamic` defines the outlined wrapper (default on; falls back to defer+NOP if missing).
# Opt-out: EXTRA_CFLAGS=-DJALV2_STRING_HEAP_COMPACT_CALL=0
echo "" >> $DST
echo "#ifndef JALV2_STRING_HEAP_COMPACT_CALL" >> $DST
echo "#define JALV2_STRING_HEAP_COMPACT_CALL 1" >> $DST
echo "#endif" >> $DST
# Optional: public `string_append` / `string_truncate` / `string_from_array` … →
# machine CALL to the outlined strings_dynamic forwarder (one shared body in
# ROM instead of the full builtin expansion at every call site).  Falls back to
# the inline builtin when the wrapper is absent or a fixed/literal source would
# have to be marshalled through a heap cell.
# Opt-out: EXTRA_CFLAGS=-DJALV2_STRING_OUTLINE_CALLS=0
echo "" >> $DST
echo "#ifndef JALV2_STRING_OUTLINE_CALLS" >> $DST
echo "#define JALV2_STRING_OUTLINE_CALLS 1" >> $DST
echo "#endif" >> $DST
